import{_ as t,o as r,c as a,ag as n}from"./chunks/framework.BPmc_f4o.js";const p=JSON.parse('{"title":"System Requirements","description":"What you need to run Muxit — supported platforms, hardware, and network requirements.","frontmatter":{"title":"System Requirements","description":"What you need to run Muxit — supported platforms, hardware, and network requirements."},"headers":[],"relativePath":"getting-started/system-requirements.md","filePath":"getting-started/system-requirements.md"}'),o={name:"getting-started/system-requirements.md"};function s(i,e,d,l,h,c){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h1><p>Muxit ships as a self-contained binary for <strong>Windows (x64)</strong>, <strong>Linux (x64 and ARM64)</strong>, and <strong>macOS (Apple Silicon and Intel)</strong>. iOS support is on the roadmap but not yet available.</p><h2 id="supported-platforms" tabindex="-1">Supported Platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported Platforms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Status</th></tr></thead><tbody><tr><td><strong>Windows 10 or later (x64)</strong></td><td>Supported today</td></tr><tr><td><strong>macOS 12+ (Apple Silicon / Intel)</strong></td><td>Supported today — see <a href="#macos-notes">macOS notes</a></td></tr><tr><td>Linux (x64 and ARM64, incl. Raspberry Pi)</td><td>Supported today</td></tr><tr><td>iOS / iPadOS</td><td>Planned</td></tr></tbody></table><h2 id="macos-notes" tabindex="-1">macOS notes <a class="header-anchor" href="#macos-notes" aria-label="Permalink to &quot;macOS notes&quot;">​</a></h2><p>macOS builds run the same self-contained server as every other platform. Cameras and AI vision work; a few OpenCV-only features don&#39;t, because there is no OpenCV native runtime for macOS (no build matches Muxit&#39;s OpenCV version, and none exists for Apple Silicon at all). Specifics:</p><ul><li><strong>Cameras work.</strong> The TestDevice video stream, USB webcams, and Onvif/RTSP IP cameras all stream and snapshot on macOS — the webcam and Onvif paths capture through the system <code>ffmpeg</code> binary and do image work with SkiaSharp instead of OpenCV. Install ffmpeg with <code>brew install ffmpeg</code>, and grant camera access under <strong>System Settings → Privacy &amp; Security → Camera</strong> for USB capture.</li><li><strong>Not available on macOS:</strong> <strong>video recording</strong> (the recorder uses OpenCV&#39;s VideoWriter) and the optional <strong>Vision detection driver</strong> (OpenCV image-analysis algorithms). Everything else — SCPI/serial/USB instruments, scripts, the AI layer (including vision/object-detection over camera frames), dashboards, MQTT, Python drivers — works normally.</li><li><strong>Builds are not yet code-signed or notarized.</strong> macOS Gatekeeper quarantines downloaded binaries. The install script clears the quarantine attribute for you. If you download a release archive by hand instead, run <code>xattr -dr com.apple.quarantine &lt;install-dir&gt;</code> once before launching.</li></ul><h2 id="hardware" tabindex="-1">Hardware <a class="header-anchor" href="#hardware" aria-label="Permalink to &quot;Hardware&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Recommended</th></tr></thead><tbody><tr><td><strong>Disk space</strong></td><td>~150 MB for the Muxit binary; workspace files grow with your own scripts and data</td></tr><tr><td><strong>Memory</strong></td><td>4 GB RAM or more</td></tr><tr><td><strong>CPU</strong></td><td>Any modern x64 or ARM64 processor (including Raspberry Pi 4 / 5)</td></tr></tbody></table><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><ul><li><strong>Outbound internet</strong> is required for AI features (chat, agents, object detection) and for license activation.</li><li><strong>Local network</strong> access is required for remote access, mDNS discovery, and any networked instruments (ONVIF cameras, TCP/IP SCPI instruments, MQTT brokers).</li><li>Muxit runs fully offline for local-only workflows once a license has been activated.</li></ul><h2 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h2><p>Muxit ships as a single self-contained package — <strong>no prerequisites to install</strong>. The .NET 9.0 runtime, V8 sandbox, and every built-in driver are bundled inside the release archive.</p><h3 id="optional-python-3-10" tabindex="-1">Optional: Python 3.10+ <a class="header-anchor" href="#optional-python-3-10" aria-label="Permalink to &quot;Optional: Python 3.10+&quot;">​</a></h3><p>Python drivers and the generic <code>Python</code> driver (used to wrap a <code>.py</code> file as a connector) need a Python 3.10+ interpreter on the host. Muxit probes the <code>MUXIT_PYTHON</code> environment variable, then <code>python3</code> on PATH, then <code>python</code> on PATH — the first usable interpreter wins. If none is found, Python drivers are silently skipped at scan time and the rest of Muxit keeps working. Install Python from <a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">python.org</a> or your package manager when you want to use this tier. See the <a href="/reference/driver-sdk-python.html">Python Driver SDK</a> for details.</p><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><p>iOS / iPadOS support is planned but not yet shipped — it would run as a client to a remote Muxit server rather than hosting one on-device. No dates have been set; the <a href="/reference/revision-history.html">Revision History</a> is the canonical place for release announcements.</p>',17)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
